 "path": "/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-openclawlearner-1790687872/attempts/0874d736f6374307823ec7507ddf4822/system/state/workspace/programs/task-1320caec.py",
 "content": "def transform(grid):
    """Fill single cells in alternating horizontal sequences between like markers."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # In examples, foreground marks are separated by a single background gap;
        # color the gap when flanked by the same mark.
        for c in range(1, len(row) - 1):
            if row[c - 1] == row[c + 1] and row[c] != row[c - 1]:
                out[r][c] = 2
    return out
